// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalDiskRecoveryTest {

	@TempDir
	Path directory;

	@Test
	void preservesFirstOccurrenceAndReadsOutOfOrderIds() throws Exception {
		ValueStoreWalConfig config = config();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(3, ValueStoreWalValueKind.BNODE, "third", "", "", 3);
			wal.logMint(1, ValueStoreWalValueKind.BNODE, "first", "", "", 1);
			wal.logMint(2, ValueStoreWalValueKind.BNODE, "second", "", "", 2);
			wal.logMint(1, ValueStoreWalValueKind.BNODE, "duplicate", "", "", 4);
		}
		Path temporary = Files.createDirectory(directory.resolve("temporary"));
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config);
				ValueStoreWalRecovery.DiskReplay replay = new ValueStoreWalRecovery().replayToDisk(reader, temporary)) {
			assertThat(replay.complete()).isTrue();
			assertThat(replay.count()).isEqualTo(3);
			assertThat(replay.maxId()).isEqualTo(3);
			assertThat(replay.hasGaps()).isFalse();
			assertThat(replay.read(1).lexical()).isEqualTo("first");
			assertThat(replay.read(2).lexical()).isEqualTo("second");
			assertThat(replay.read(3).lexical()).isEqualTo("third");
			assertThat(replay.read(1).hash()).isEqualTo(1);
			assertThat(replay.read(3).lsn()).isEqualTo(1L);
		}
		assertEmpty(temporary);
	}

	@Test
	void supportsLongUnicodeStringsWithoutWriteUtfLimit() throws Exception {
		ValueStoreWalConfig config = config();
		String lexical = "\u00e6\u6f22\uD83D\uDE42".repeat(40_000);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, lexical, "urn:datatype", "nb", 7);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config);
				ValueStoreWalRecovery.DiskReplay replay = new ValueStoreWalRecovery().replayToDisk(reader, directory)) {
			ValueStoreWalRecord record = replay.read(1);
			assertThat(record.lexical()).isEqualTo(lexical);
			assertThat(record.datatype()).isEqualTo("urn:datatype");
			assertThat(record.language()).isEqualTo("nb");
		}
	}

	@Test
	void keepsSparseHighIdsOnDiskAndReportsGaps() throws Exception {
		ValueStoreWalConfig config = config();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(Integer.MAX_VALUE, ValueStoreWalValueKind.BNODE, "last", "", "", 0);
			wal.logMint(32_768, ValueStoreWalValueKind.BNODE, "middle", "", "", 0);
			wal.logMint(1, ValueStoreWalValueKind.BNODE, "first", "", "", 0);
		}
		Path temporary = Files.createDirectory(directory.resolve("temporary"));
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config);
				ValueStoreWalRecovery.DiskReplay replay = new ValueStoreWalRecovery().replayToDisk(reader, temporary)) {
			assertThat(replay.count()).isEqualTo(3);
			assertThat(replay.maxId()).isEqualTo(Integer.MAX_VALUE);
			assertThat(replay.hasGaps()).isTrue();
			assertThat(replay.read(2)).isNull();
			assertThat(replay.read(Integer.MAX_VALUE).lexical()).isEqualTo("last");
			assertThat(replay.read(32_768).lexical()).isEqualTo("middle");
			assertThat(replay.read(1).lexical()).isEqualTo("first");
		}
		assertEmpty(temporary);
	}

	@Test
	void cleansTemporaryFilesWhenReplayFails() throws Exception {
		ValueStoreWalConfig config = config();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.BNODE, "first", "", "", 0);
			wal.logMint(0, ValueStoreWalValueKind.BNODE, "invalid", "", "", 0);
		}
		Path temporary = Files.createDirectory(directory.resolve("temporary"));
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			assertThatThrownBy(() -> new ValueStoreWalRecovery().replayToDisk(reader, temporary))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("id");
		}
		assertEmpty(temporary);
	}

	@Test
	void reportsIncompleteWalAndCleansTemporaryFiles() throws Exception {
		ValueStoreWalConfig config = config();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.BNODE, "first", "", "", 0);
		}
		Path segment;
		try (var files = Files.list(config.walDirectory())) {
			segment = files.filter(p -> p.getFileName().toString().endsWith(".v1")).findFirst().orElseThrow();
		}
		Files.write(segment, new byte[] { 1, 2 }, StandardOpenOption.APPEND);
		Path temporary = Files.createDirectory(directory.resolve("temporary"));
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config);
				ValueStoreWalRecovery.DiskReplay replay = new ValueStoreWalRecovery().replayToDisk(reader, temporary)) {
			assertThat(replay.complete()).isFalse();
			assertThat(replay.read(1).lexical()).isEqualTo("first");
		}
		assertEmpty(temporary);
	}

	private ValueStoreWalConfig config() {
		return ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("wal"))
				.storeUuid("disk-replay")
				.recoverValueStoreOnOpen(true)
				.build();
	}

	private static void assertEmpty(Path directory) throws IOException {
		try (var files = Files.list(directory)) {
			assertThat(files).isEmpty();
		}
	}
}
